package com.yuyutian.mytools.media.library.controller;
import org.springframework.http.*;import org.springframework.web.bind.MethodArgumentNotValidException;import org.springframework.web.bind.annotation.*;import java.util.Map;
/** Media API 异常映射。 */ @RestControllerAdvice public class MediaExceptionHandler { /** 未授权。 @param exception 异常 @return 错误 */ @ExceptionHandler(SecurityException.class) public ResponseEntity<Map<String,String>> unauthorized(SecurityException exception){return ResponseEntity.status(401).body(Map.of("code","MEDIA_001","message","Unauthorized"));} /** 输入或冲突。 @param exception 异常 @return 错误 */ @ExceptionHandler({IllegalArgumentException.class,IllegalStateException.class,MethodArgumentNotValidException.class}) public ResponseEntity<Map<String,String>> invalid(Exception exception){HttpStatus status=exception instanceof IllegalStateException?HttpStatus.CONFLICT:HttpStatus.BAD_REQUEST;return ResponseEntity.status(status).body(Map.of("code",status==HttpStatus.CONFLICT?"MEDIA_003":"MEDIA_002","message",status.getReasonPhrase()));} }
